/// Removes every table, so the database starts empty.
const DROP: &[&str] = &[
    "DROP TABLE IF EXISTS \"audit_log\" CASCADE",
    "DROP TABLE IF EXISTS \"product_tags\" CASCADE",
    "DROP TABLE IF EXISTS \"tags\" CASCADE",
    "DROP TABLE IF EXISTS \"order_lines\" CASCADE",
    "DROP TABLE IF EXISTS \"orders\" CASCADE",
    "DROP TABLE IF EXISTS \"products\" CASCADE",
    "DROP TABLE IF EXISTS \"categories\" CASCADE",
    "DROP TABLE IF EXISTS \"customers\" CASCADE",
];

/// Creates every table, in an order the database accepts.
const CREATE: &[&str] = &[
    "CREATE TABLE \"customers\" (\n  \"id\" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,\n  \"email\" varchar(120) NOT NULL,\n  \"password_hash\" text NOT NULL,\n  \"created_at\" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (\"id\"),\n  CONSTRAINT \"uq_customers_email\" UNIQUE (\"email\")\n)",
    "CREATE TABLE \"categories\" (\n  \"id\" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,\n  \"name\" varchar(60) NOT NULL,\n  PRIMARY KEY (\"id\"),\n  UNIQUE (\"name\")\n)",
    "CREATE TABLE \"products\" (\n  \"id\" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,\n  \"category_id\" bigint NOT NULL,\n  \"name\" varchar(100) NOT NULL,\n  \"price\" numeric(10,2) NOT NULL,\n  \"status\" varchar(10) NOT NULL,\n  \"version\" integer NOT NULL DEFAULT 1,\n  \"deleted_at\" timestamptz,\n  PRIMARY KEY (\"id\"),\n  CHECK (\"price\" >= 0),\n  CONSTRAINT \"fk_products_category\" FOREIGN KEY (\"category_id\") REFERENCES \"categories\" (\"id\")\n)",
    "CREATE INDEX \"ix_products_status\" ON \"products\" (\"status\")",
    "CREATE INDEX \"ix_products_category_id\" ON \"products\" (\"category_id\")",
    "CREATE TABLE \"orders\" (\n  \"id\" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,\n  \"customer_id\" bigint NOT NULL,\n  \"placed_at\" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (\"id\"),\n  FOREIGN KEY (\"customer_id\") REFERENCES \"customers\" (\"id\")\n)",
    "CREATE TABLE \"order_lines\" (\n  \"order_id\" bigint NOT NULL,\n  \"line\" integer NOT NULL,\n  \"product_id\" bigint NOT NULL,\n  \"quantity\" integer NOT NULL,\n  PRIMARY KEY (\"order_id\", \"line\"),\n  FOREIGN KEY (\"order_id\") REFERENCES \"orders\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"product_id\") REFERENCES \"products\" (\"id\") ON DELETE RESTRICT\n)",
    "CREATE TABLE \"tags\" (\n  \"id\" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,\n  \"label\" varchar(30) NOT NULL,\n  PRIMARY KEY (\"id\")\n)",
    "CREATE TABLE \"product_tags\" (\n  \"product_id\" bigint NOT NULL,\n  \"tag_id\" bigint NOT NULL,\n  PRIMARY KEY (\"product_id\", \"tag_id\"),\n  FOREIGN KEY (\"product_id\") REFERENCES \"products\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"tag_id\") REFERENCES \"tags\" (\"id\") ON DELETE CASCADE\n)",
    "CREATE TABLE \"audit_log\" (\n  \"at\" timestamptz NOT NULL,\n  \"message\" text NOT NULL\n)",
];

/// Every test empties the same database: they take turns
static TURN: Mutex<()> = Mutex::const_new(());

/// A pool of connections to the test database.
async fn connect() -> Pool {
    // The tables are written for one kind of database: the tests cannot fall back to SQLite
    let url = std::env::var("TEST_DATABASE_URL").expect("The database tests need a disposable PostgreSQL database: set TEST_DATABASE_URL (it is emptied)");
    Pool::connect(&url).await.expect("the test database")
}

/// The repositories over the test database, with every table dropped and created again, and the turn of the test
/// that holds it.
pub async fn open() -> (MutexGuard<'static, ()>, SqlUnitOfWork) {
    let turn = TURN.lock().await;
    let pool = connect().await;
    // On one connection, as MySQL turns its foreign key checks off for the connection that asks
    let mut connection = pool.acquire().await.expect("a connection");
    for sql in DROP.iter().chain(CREATE) {
        sqlx::raw_sql(*sql).execute(&mut *connection).await.expect(sql);
    }
    drop(connection);
    (turn, SqlUnitOfWork::new(pool))
}

#[tokio::test]
async fn is_the_one_test_database_url_names() {
    let _turn = TURN.lock().await;
    let row = sqlx::query("SELECT current_database()").fetch_one(&connect().await).await.expect("a row");
    let value: String = row.try_get(0).expect("a value");
    let url = std::env::var("TEST_DATABASE_URL").expect("TEST_DATABASE_URL");
    assert_eq!(url.rsplit('/').next().and_then(|name| name.split('?').next()), Some(value.as_str()));
}

