//! The service of the "tags" table, on the in-memory repositories.

use rust_sql_postgresql_dtos_patch_cursor::common::Patch;
use rust_sql_postgresql_dtos_patch_cursor::dtos::tag::{TagCreate, TagUpdate};
use rust_sql_postgresql_dtos_patch_cursor::entities::tag::Tag;
use rust_sql_postgresql_dtos_patch_cursor::errors::DomainError;
use rust_sql_postgresql_dtos_patch_cursor::services::tag::TagService;
use rust_sql_postgresql_dtos_patch_cursor::unit_of_work::MemoryUnitOfWork;
use std::sync::Arc;
use super::factories;

#[tokio::test]
async fn creates_a_valid_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = TagService::new(uow.clone());
    let row = factories::new_tag(1);
    let created = service.create_tag(create_of(row)).await.expect("a create");
    let found = service.get_tag(created.id).await.expect("a read");
    assert_eq!(created.id, found.id);
}

#[tokio::test]
async fn refuses_a_missing_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = TagService::new(uow.clone());
    let mut row = factories::new_tag(1);
    row.label = None;
    let error = service.create_tag(create_of(row)).await.expect_err("a refusal");
    let DomainError::ValidationFailed { errors, .. } = &error else { panic!("{error}") };
    assert_eq!(vec!["label"], errors.iter().map(|error| error.field.as_str()).collect::<Vec<_>>());
}

#[tokio::test]
async fn says_when_a_row_is_missing() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = TagService::new(uow.clone());
    assert!(matches!(service.get_tag(999999).await, Err(DomainError::NotFound { .. })));
}

#[tokio::test]
async fn changes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = TagService::new(uow.clone());
    let row = factories::new_tag(1);
    let created = service.create_tag(create_of(row.clone())).await.expect("a create");
    let updated = service.update_tag(created.id, TagUpdate { label: Patch::Set(Some("changed".to_string())), ..Default::default() }).await.expect("an update");
    assert_eq!(updated.label, "changed");
}

#[tokio::test]
async fn deletes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = TagService::new(uow.clone());
    let row = factories::new_tag(1);
    let created = service.create_tag(create_of(row)).await.expect("a create");
    service.delete_tag(created.id).await.expect("a delete");
    assert!(matches!(service.get_tag(created.id).await, Err(DomainError::NotFound { .. })));
}

/// The create DTO of a row the factories made.
fn create_of(row: Tag) -> TagCreate {
    TagCreate { label: row.label }
}
